import time
from web3 import Web3

# Connect to Node 1 JSON-RPC endpoint
w3 = Web3(Web3.HTTPProvider('http://127.0.0.1:8541'))

if not w3.is_connected():
    print("❌ Error: Cannot connect to Node 1 RPC")
    exit(1)

# Load Node 1 private key generated by the Besu operator tool
with open('qbft_network/node1/data/key', 'r') as key_file:
    private_key = key_file.read().strip()

# Convert raw string addresses to EIP-55 checksum addresses required by web3.py
sender_address = Web3.to_checksum_address('0x117817b801e9bcc679eaf37c9f22b06605a484eb')
receiver_address = Web3.to_checksum_address('0x0000000000000000000000000000000000000000')

print(f"📊 Initial Balance: {w3.from_wei(w3.eth.get_balance(sender_address), 'ether')} ETH")

# Get the initial nonce for the sender account
nonce = w3.eth.get_transaction_count(sender_address)

# Send 5 test transactions in a quick loop to populate the pool
for i in range(5):
    tx = {
        'nonce': nonce,
        'to': receiver_address,
        'value': w3.to_wei(0.01, 'ether'),
        'gas': 21000,
        'gasPrice': w3.eth.gas_price,
        'chainId': 1337
    }

    # Sign the transaction locally using the private key
    signed_tx = w3.eth.account.sign_transaction(tx, private_key)

    # Send the raw transaction to the transaction pool
    tx_hash = w3.eth.send_raw_transaction(signed_tx.raw_transaction)
    print(f"🚀 Sent TX #{i+1} | Nonce: {nonce} | Hash: {tx_hash.hex()}")

    nonce += 1
    time.sleep(0.1) # Short delay to simulate real traffic

print("⏳ Waiting for transaction execution metrics...")